latihan-algoritma-fibonacci-bubble-sort-.code:
fun main() {
    // 1. Fibonacci: 10 suku pertama, a dan b bergeser setiap putaran
    var a = 0
    var b = 1
    print("Fibonacci:")
    for (i in 1..10) {
        print(" $a")
        val c = a + b
        a = b
        b = c
    }
    println()

    // 2. Bubble sort: tukar pasangan yang terbalik sampai tidak ada pertukaran
    val data = mutableListOf(64, 25, 12, 22, 11)
    var adaTukar = true
    while (adaTukar) {
        adaTukar = false
        for (j in 0 until data.size - 1) {
            if (data[j] > data[j + 1]) {
                val t = data[j]
                data[j] = data[j + 1]
                data[j + 1] = t
                adaTukar = true
            }
        }
    }
    println("Terurut: $data")

    // 3. Prima: cari pembagi dari 2 sampai akar x
    print("Prima:")
    for (x in 2..30) {
        var prima = true
        var d = 2
        while (d * d <= x) {
            if (x % d == 0) prima = false
            d++
        }
        if (prima) print(" $x")
    }
    println()
}

