class Rekening(val pemilik: String, var saldo: Int) {
    fun setor(jumlah: Int) {
        saldo += jumlah
    }

    fun tarik(jumlah: Int): Boolean {
        if (jumlah > saldo) return false
        saldo -= jumlah
        return true
    }
}

fun main() {
    val rek = Rekening("Siti Aminah", 200_000)
    rek.setor(50_000)
