import kotlin.math.roundToInt

data class Item(val nama: String, val harga: Int, val qty: Int) {
    val subtotal: Int get() = harga * qty
}

fun rp(n: Int) = n.toString().reversed().chunked(3).joinToString(".").reversed()

fun main() {
    val keranjang = listOf(Item("Nasi rendang", 28000, 1), Item("Es teh", 5500, 3))
    val subtotal = keranjang.sumOf { it.subtotal }
    val ppn = (subtotal * 0.11).roundToInt()
    for (b in keranjang) println("${b.nama} x${b.qty}".padEnd(18) + rp(b.subtotal).padStart(8))
    println("Subtotal".padEnd(18) + rp(subtotal).padStart(8))
    println("PPN 11%".padEnd(18) + rp(ppn).padStart(8))
    println("Total".padEnd(18) + rp(subtotal + ppn).padStart(8))
}

fun rp(n: Int) = "Rp" + n.toString().reversed().chunked(3).joinToString(".").reversed()

fun bayarTunai(total: Int, uang: Int): Int {
    require(uang >= total) { "Uang kurang ${rp(total - uang)}" }
    return uang - total
}

fun main() {
    val total = 66_150
    for (uang in listOf(100_000, 70_000, 50_000)) {
        val hasil = runCatching { bayarTunai(total, uang) }
        hasil.onSuccess { println("Bayar ${rp(uang)}, kembali ${rp(it)}") }
        hasil.onFailure { println("Bayar ${rp(uang)} ditolak: ${it.message}") }
    }
}

data class Item(val nama: String, val kategori: String, val harga: Int)

fun diskonPersen(kategori: String) = when (kategori) {
