import kotlin.math.sqrt

data class Titik(val x: Double, val y: Double) {
    operator fun minus(lain: Titik) = Titik(x - lain.x, y - lain.y)
    infix fun jarakKe(lain: Titik): Double {
        val d = this - lain
        return sqrt(d.x * d.x + d.y * d.y)
    }
}

fun main() {
